# HonuHuliHuli - pushbutton turntable indexer for MicroPython on ESP32.
#
# A 200 step/rev stepper drives the turntable directly through a STEP/DIR
# driver.  STEP and an active-high ENABLE are driven; DIR is hardwired.
#
#   Short press        index 1/8 turn (relative to wherever the table is).
#                      Presses accumulate: three quick presses play three
#                      1/8 moves back to back.
#   Hold > 1 second    start continuous rotation (as soon as 1 s is reached).
#   Any press while    decelerate to a stop.
#   rotating
#
# Step pulses are generated by the RMT peripheral.  Every pulse train is
# precomputed at startup as a few fixed "pieces" (the acceleration ramp cut
# into pieces of at most PIECE_MS, their reversals for deceleration, one
# cruise piece and one complete 1/8 index move), so running needs no float
# math and creates no garbage: each time the RMT finishes a piece, poll()
# hands it the next ready-made list.  A stop takes effect at the next piece
# boundary.  MicroPython's write_pulses() waits for the previous
# transmission to finish, so the only exposure to Python delays (web
# requests, GC) is at those handoffs; stats() reports how late they were.

from machine import Pin, Timer
from micropython import const
from time import ticks_ms, ticks_us, ticks_add, ticks_diff, sleep_ms
from math import sqrt, sin, cos
import esp32
import asyncio
import gc

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

import pins                  # D1 mini pin names for this board

BUTTON_PIN = pins.D3      # GPIO to the pushbutton (D3)
UV_PIN = pins.D4          # GPIO to the UV light relay (active high); on (D4)
STEP_PIN = pins.D5        # GPIO to the driver's STEP input (D5)
ENABLE_PIN = pins.D6      # GPIO to the driver's ENABLE input (active high) (D6)
ENABLE_AT_BOOT = True    # Energize the motor when the app starts
OLED_SDA_PIN = pins.D2
OLED_SCL_PIN = pins.D1
OLED_ADDR = const(0x3C)
STATE_ROW = const(5)          # OLED row for Index/Run
BUTTON_ACTIVE_LOW = True # True: button to GND, internal pull-up enabled

FULL_STEPS_PER_REV = const(200)
MICROSTEPS = const(32)       # Must match the driver's microstep setting

ACCELERATION = 0.3           # rev/s^2, used for all speed changes
CONTINUOUS_RPM = 20.0        # Speed for continuous rotation
INDEX_RPM = 40.0             # Top speed for 1/8 index moves (short moves


DIVISIONS = const(8)         # Index increment is 1/DIVISIONS of a turn
LONG_PRESS_MS = const(1000)  # Hold this long to start continuous rotation
DEBOUNCE_MS = const(30)

STEP_PULSE_US = const(5)     # STEP high time; check the driver's minimum
RMT_CHANNEL = const(0)
PIECE_MS = const(500)        # Max duration of each ramp piece; a stop
                             # takes effect at the next piece boundary
CRUISE_MS = const(100)       # Duration of the repeated cruise piece.  Each
                             # handoff has a gap while write_pulses() converts
                             # the list (~0.5 us per step), so keep it short
SPIN_US = const(3000)        # The handoff timer fires this long before a
                             # piece ends; the callback waits out the rest
HANDOFF_TIMER = const(0)     # machine.Timer id used for piece handoffs
LATE_US = const(1000)        # A handoff later than this counts as late

# ---------------------------------------------------------------------------

STEPS_PER_REV = FULL_STEPS_PER_REV * MICROSTEPS
STEPS_PER_INDEX = STEPS_PER_REV // DIVISIONS

TICKS_PER_SEC = 1_000_000    # RMT tick is 1 us
MAX_TICKS = 32767            # RMT 15-bit duration field

ACCEL_STEPS = ACCELERATION * STEPS_PER_REV       # steps/s^2
TWO_A = 2.0 * ACCEL_STEPS                         # v^2 change per step
CONT_V2 = (CONTINUOUS_RPM / 60.0 * STEPS_PER_REV) ** 2
INDEX_V2 = (INDEX_RPM / 60.0 * STEPS_PER_REV) ** 2

# Starting/stopping speed: the speed reached after one step from rest, but
# never slower than the longest interval the RMT can express in one item.
_min_v = TICKS_PER_SEC / (MAX_TICKS + STEP_PULSE_US - 1)
START_V2 = max(TWO_A, _min_v * _min_v)

PIECE_TICKS = PIECE_MS * (TICKS_PER_SEC // 1000)
CRUISE_TICKS = CRUISE_MS * (TICKS_PER_SEC // 1000)
MAX_INTERVAL = MAX_TICKS + STEP_PULSE_US - 1


def make_rmt():
    pin = Pin(STEP_PIN, Pin.OUT, value=0)
    # The esp32.RMT constructor changed when MicroPython moved to the
    # ESP-IDF 5 RMT driver; try the newer form first, then the older one.
    try:
        return esp32.RMT(RMT_CHANNEL, pin=pin, resolution_hz=TICKS_PER_SEC,
                         idle_level=False)
    except (TypeError, ValueError):
        pass
    # Older API: ticks are source_freq / clock_div (source is 80 MHz).
    return esp32.RMT(RMT_CHANNEL, pin=pin, clock_div=80, idle_level=False)


def _ramp(limit_v2, max_steps=None):
    """Yield integer step intervals (RMT ticks) accelerating from rest,
    with v^2 growing by 2a per step (constant acceleration), until the
    speed reaches limit_v2 or max_steps intervals have been produced.
    Carries the fractional tick so the average rate is exact.  A generator,
    so no list of float speeds is ever held in memory."""
    frac = 0.0
    v2 = START_V2
    n = 0
    while v2 < limit_v2 and (max_steps is None or n < max_steps):
        frac += TICKS_PER_SEC / sqrt(v2)
        t = int(frac)
        frac -= t
        yield min(t, MAX_INTERVAL)
        v2 += TWO_A
        n += 1


def _constant(v2, n):
    """n integer step intervals at a constant squared speed v2."""
    iv = TICKS_PER_SEC / sqrt(v2)
    frac = 0.0
    out = [0] * n            # exact size; append() would over-allocate
    for i in range(n):
        frac += iv
        t = int(frac)
        frac -= t
        out[i] = min(t, MAX_INTERVAL)
    return out


def _pulses(intervals):
    """RMT durations [high, low, high, low, ...] for a list of intervals.
    Allocated at exact size: MicroPython grows an appended-to list by
    doubling, which could waste up to half of each table."""
    out = [STEP_PULSE_US] * (2 * len(intervals))
    for i in range(len(intervals)):
        out[2 * i + 1] = intervals[i] - STEP_PULSE_US
    return out


def _split(intervals):
    """Cut a sequence of intervals into pieces of at most about
    PIECE_TICKS."""
    pieces = []
    cur = []
    t = 0
    for iv in intervals:
        cur.append(iv)
        t += iv
        if t >= PIECE_TICKS:
            pieces.append(cur)
            cur = []
            t = 0
    if cur:
        pieces.append(cur)
    return pieces


class Piece:
    """A precomputed pulse train ready for rmt.write_pulses()."""

    def __init__(self, intervals):
        self.pulses = _pulses(intervals)
        self.steps = len(intervals)
        self.us = sum(intervals)


class Profiles:
    """All the pulse trains the turntable plays, built once at startup.

    up[k] accelerates from speed s(k) to s(k+1); down[k] is up[k] played
    backwards, s(k+1) to s(k).  So a move can turn around at any piece
    boundary: after up[k], decelerate with down[k], down[k-1], ... down[0];
    after down[k], accelerate again with up[k].
    """

    def __init__(self):
        # Only small-int interval lists are held while building; the float
        # math happens one step at a time in the generators, so the peak
        # memory is little more than the finished tables.
        ramp = _split(_ramp(CONT_V2))
        self.up = [Piece(p) for p in ramp]
        self.down = [Piece(p[::-1]) for p in ramp]
        ramp = None

        # One cruise piece, repeated while running
        n = max(1, round(CRUISE_TICKS * sqrt(CONT_V2) / TICKS_PER_SEC))
        self.cruise = Piece(_constant(CONT_V2, n))

        # A complete 1/8 move: accelerate toward INDEX_RPM, cruise if it
        # gets there, and decelerate symmetrically, in exactly
        # STEPS_PER_INDEX steps.
        up = list(_ramp(INDEX_V2, STEPS_PER_INDEX // 2))
        middle = _constant(INDEX_V2, STEPS_PER_INDEX - 2 * len(up))
        self.index = Piece(up + middle + up[::-1])


PRESS = const(1)
RELEASE = const(2)
LONG = const(3)


class Button:
    def __init__(self, gpio):
        pull = Pin.PULL_UP if BUTTON_ACTIVE_LOW else Pin.PULL_DOWN
        self.pin = Pin(gpio, Pin.IN, pull)
        sleep_ms(DEBOUNCE_MS)    # let the pull settle
        self.raw = self.read()
        self.stable = self.raw
        self.changed_t = ticks_ms()
        self.press_t = 0
        # A press held from power-up never counts as a long press
        self.long_sent = self.stable

    def read(self):
        return self.pin.value() == (0 if BUTTON_ACTIVE_LOW else 1)

    def poll(self):
        """Return PRESS, RELEASE, LONG, or None."""
        now = ticks_ms()
        raw = self.read()
        if raw != self.raw:
            self.raw = raw
            self.changed_t = now
            return None
        if raw != self.stable and ticks_diff(now, self.changed_t) >= DEBOUNCE_MS:
            self.stable = raw
            if raw:
                self.press_t = now
                self.long_sent = False
                return PRESS
            return RELEASE
        if (self.stable and not self.long_sent
                and ticks_diff(now, self.press_t) >= LONG_PRESS_MS):
            self.long_sent = True
            return LONG
        return None


def check_config():
    if STEPS_PER_REV % DIVISIONS:
        raise ValueError("STEPS_PER_REV not divisible by DIVISIONS")
    min_interval = TICKS_PER_SEC / sqrt(max(CONT_V2, INDEX_V2))
    if min_interval < 2 * STEP_PULSE_US:
        raise ValueError("Speed too high for STEP_PULSE_US")


def fmt_time(s):
    """Seconds as m:ss, or h:mm:ss from an hour up."""
    m, s = divmod(s, 60)
    if m < 60:
        return "%d:%02d" % (m, s)
    h, m = divmod(m, 60)
    return "%d:%02d:%02d" % (h, m, s)


IDLE = const(0)
INDEX = const(1)
UP = const(2)
CRUISE = const(3)
DOWN = const(4)
STATE_NAMES = ("idle", "index", "up", "cruise", "down")


class Turntable:
    def __init__(self, oled=None):
        check_config()
        self.oled = oled
        self.state_label = ""
        self.shown_secs = None   # remaining seconds last shown
        self.enable_pin = Pin(ENABLE_PIN, Pin.OUT, value=ENABLE_AT_BOOT)
        self.rmt = make_rmt()
        self.button = Button(BUTTON_PIN)
        self.uv_pin = Pin(UV_PIN, Pin.OUT, value=0)
        self.prof = None         # built by build(), after WiFi is up
        self.state = IDLE        # what the RMT is playing
        self.k = 0               # which up/down piece, in UP and DOWN
        self.want_run = False    # continuous rotation requested
        self.pending_index = 0   # queued 1/8 moves
        self.pos = 0             # microsteps sent since power-up
        self.piece_end = None    # ticks_us when the playing piece ends
        self.moved = False       # a piece has been played since last idle
        self.finished = False    # set by the timer callback at end of a move
        self.timer = Timer(HANDOFF_TIMER)
        self.armed = False       # handoff timer pending
        self.fire_at = 0         # ticks_us the timer is due
        self.handing_off = False
        self.reset_stats()
        # True when the current press has already been used (to stop
        # continuous rotation or to start it), so its release is not a
        # short press.  A press held from power-up is ignored.
        self.consumed = self.button.stable
        # ticks_ms at which a timed continuous run stops, or None
        self.run_deadline = None

    def build(self):
        """Precompute the pulse tables.  Call after WiFi has started: the
        tables grow MicroPython's heap, which takes memory from the ESP-IDF
        heap that the WiFi driver allocates from."""
        gc.collect()
        self.prof = Profiles()
        gc.collect()

    # Non-blocking commands, shared by the button, REPL and web interface

    def show_remaining(self):
        """Count down a timed run on the state row, stopping at zero."""
        ms = ticks_diff(self.run_deadline, ticks_ms())
        if ms <= 0:
            self.stop()
            return
        secs = (ms + 999) // 1000
        if secs != self.shown_secs:
            self.shown_secs = secs
            self.show_state(fmt_time(secs))

    def show_state(self, label):
        """Show Index/Run on the OLED's bottom row; "" clears it, which
        leaves the signon (or access point info) above it."""
        if label != self.state_label:
            self.state_label = label
            if self.oled is not None:
                self.oled.center(STATE_ROW, label)

    def start(self, seconds=None):
        """Start continuous rotation, optionally stopping after seconds.
        During a 1/8 move it starts once that move ends; queued 1/8 moves
        are dropped."""
        self.want_run = True
        self.shown_secs = None
        if seconds is None:
            self.run_deadline = None
            self.show_state("Run")
        else:
            self.run_deadline = ticks_add(ticks_ms(), int(seconds * 1000))
            self.show_remaining()

    def stop(self):
        """Stop continuous rotation: decelerate from the next piece
        boundary."""
        self.run_deadline = None
        if self.want_run:
            self.want_run = False
            self.uv(False)

    def add_index(self, n=1):
        """Queue n 1/8 moves (ignored while rotating continuously)."""
        if self.want_run or n < 1:
            return
        self.pending_index += n
        self.show_state("Index")

    def uv(self, on):
        self.uv_pin.value(1 if on else 0)

    def status(self):
        remaining = None
        if self.want_run:
            state = "running"
            if self.run_deadline is not None:
                remaining = max(0, ticks_diff(self.run_deadline, ticks_ms())) // 1000
        elif self.state != IDLE or self.pending_index or self.armed:
            state = "moving"
        else:
            state = "idle"
        return {"state": state, "remaining": remaining,
                "uv": bool(self.uv_pin.value()),
                "enabled": bool(self.enable_pin.value())}

    def _next_piece(self):
        """Choose what to play after the current piece ends (or when idle).
        Returns a Piece, or None to stay idle."""
        if self.prof is None:
            self.build()         # e.g. REPL use after Ctrl-C during WiFi
        p = self.prof
        st = self.state
        if st == UP:
            if not self.want_run:
                self.state = DOWN
                return p.down[self.k]
            if self.k + 1 < len(p.up):
                self.k += 1
                return p.up[self.k]
            return self._cruise()
        if st == CRUISE:
            if self.want_run:
                return p.cruise
            if p.down:
                self.state = DOWN
                self.k = len(p.down) - 1
                return p.down[self.k]
        elif st == DOWN:
            if self.want_run:
                self.state = UP
                return p.up[self.k]
            if self.k > 0:
                self.k -= 1
                return p.down[self.k]
        # At rest: after a 1/8 move, at the end of deceleration, or idle
        if self.want_run:
            self.pending_index = 0
            if not p.up:
                return self._cruise()
            self.state = UP
            self.k = 0
            return p.up[0]
        if self.pending_index:
            self.pending_index -= 1
            self.state = INDEX
            return p.index
        self.state = IDLE
        return None

    def _cruise(self):
        self.state = CRUISE
        self.uv(True)            # light on once at speed
        return self.prof.cruise

    # Piece handoff.  While moving, a one-shot machine.Timer fires shortly
    # before the playing piece ends; its callback waits out the rest and
    # writes the next piece.  Timer callbacks are soft interrupts that
    # MicroPython runs between bytecodes of whatever Python code is
    # executing, so a web request being handled in the asyncio loop cannot
    # delay a handoff the way it delayed a polled one.  Only C code that
    # runs for a long time (a socket call, an I2C transfer, GC) can.
    # The callback must not touch the OLED: it may run between two steps of
    # the main code's own display update.

    def _arm(self, us):
        """Arm the handoff timer to fire SPIN_US before us from now."""
        ms = max(1, (us - SPIN_US) // 1000)
        self.fire_at = ticks_add(ticks_us(), ms * 1000)
        self.armed = True
        self.timer.init(mode=Timer.ONE_SHOT, period=ms, callback=self._on_timer)

    def _on_timer(self, _t):
        self.armed = False
        if self.handing_off:
            # Interrupted a handoff that poll() started; try again shortly
            self._arm(SPIN_US + 1000)
            return
        delay = ticks_diff(ticks_us(), self.fire_at)
        if delay > self.cb_delay_max:
            self.cb_delay_max = delay
        limit = ticks_add(self.piece_end, SPIN_US)
        while not self.rmt.wait_done():
            if ticks_diff(ticks_us(), limit) > 0:
                # The RMT is running long; look again in a millisecond
                self._arm(SPIN_US + 1000)
                return
        self._handoff(delay)

    def _handoff(self, delay=0):
        """The RMT is idle: write the next piece, or finish the move."""
        self.handing_off = True
        try:
            prev = self.state
            piece = self._next_piece()
            if piece is None:
                self.piece_end = None
                if self.moved:
                    self.moved = False
                    self.finished = True     # poll() reports and clears
                return
            now = ticks_us()
            if self.piece_end is not None:
                # Back-to-back: how long after the previous piece ended?
                late = ticks_diff(now, self.piece_end)
                self.handoffs += 1
                if late > self.late_max:
                    self.late_max = late
                if late > LATE_US:
                    self.late_count += 1
                    if len(self.late_log) < 8:
                        self.late_log.append((late, delay, prev))
            self.rmt.write_pulses(piece.pulses, True)
            t = ticks_us()
            w = ticks_diff(t, now)
            if w > self.write_max:
                self.write_max = w
            self.piece_end = ticks_add(t, piece.us)
            self.pos += piece.steps
            self.moved = True
            self._arm(piece.us)
        finally:
            self.handing_off = False

    def moving(self):
        return self.armed or self.state != IDLE

    def poll(self):
        """Button handling, starting a move from rest, and end-of-move
        reporting.  Returns True while moving."""
        ev = self.button.poll()
        if ev == PRESS:
            self.consumed = False
            if self.want_run:
                self.stop()
                self.consumed = True
        elif ev == LONG:
            if not self.consumed:
                self.start()
                self.consumed = True
        elif ev == RELEASE:
            if not self.consumed:
                self.add_index()

        if self.run_deadline is not None:
            self.show_remaining()

        if self.finished:
            self.finished = False
            if self.state_label:
                self.show_state("")
            self.stats()         # handoff timing for the move just ended

        if self.armed:
            # Safety net: if the timer callback never ran, take over
            if (self.piece_end is not None
                    and ticks_diff(ticks_us(), self.piece_end) > 100_000):
                self.timer.deinit()
                self.armed = False
                self.rescued += 1
                self._handoff()
            return True
        if self.state == IDLE and (self.want_run or self.pending_index):
            if self.rmt.wait_done():
                self._handoff()      # start a move from rest
            return True
        return self.moving()

    def reset_stats(self):
        self.handoffs = 0
        self.late_count = 0
        self.late_max = 0
        self.cb_delay_max = 0    # longest timer callback delay
        self.write_max = 0       # longest write_pulses() call
        self.rescued = 0         # handoffs poll() took over from the timer
        self.late_log = []       # (late us, callback delay, state)

    def stats(self, reset=True):
        """Print handoff timing.  For each late handoff, "cb delay" is how
        long after its due time the timer callback ran: a delay close to the
        lateness means Python was blocked in C code (or the core was taken
        by an ESP-IDF task); a small delay means the RMT finished later than
        its computed end time."""
        print("handoffs %d, late (>%d us) %d, latest %d us, "
              "max cb delay %d us, max write %d us%s"
              % (self.handoffs, LATE_US, self.late_count, self.late_max,
                 self.cb_delay_max, self.write_max,
                 ", rescued %d" % self.rescued if self.rescued else ""))
        for late, delay, st in self.late_log:
            print("  late %d us, cb delay %d us, after %s"
                  % (late, delay, STATE_NAMES[st]))
        if reset:
            self.reset_stats()

    def abort(self):
        """Abandon any motion.  The piece already in the RMT plays out, so
        the table stops abruptly."""
        self.timer.deinit()
        self.armed = False
        self.want_run = False
        self.pending_index = 0
        self.state = IDLE
        self.piece_end = None
        self.finished = False
        self.moved = False
        self.run_deadline = None
        self.uv(False)
        self.show_state("")
        print("Stopped at step", self.pos)

    def loop(self):
        """Run the pushbutton controller forever."""
        try:
            while True:
                self.poll()
                sleep_ms(5)      # timer callbacks run during the sleep
        except KeyboardInterrupt:
            self.abort()
            raise

    async def poll_task(self):
        """asyncio version of loop(), run alongside the web server."""
        while True:
            self.poll()
            await asyncio.sleep_ms(5)

    def wait(self):
        """Poll until all motion has finished."""
        try:
            while self.poll():
                sleep_ms(1)
        except KeyboardInterrupt:
            self.abort()
            raise

    # Blocking REPL commands

    def index(self, n=1):
        """Index n eighths of a turn and wait for the moves to finish."""
        if n < 1:
            raise ValueError("n must be >= 1")
        self.stop()
        self.add_index(n)
        self.wait()

    def run(self, seconds):
        """Rotate continuously for the given time, then decelerate to a
        stop and wait for it."""
        self.start(seconds)
        self.wait()

    def step(self, n=1, interval_ms=10):
        """Send n single microsteps at interval_ms apart and wait, then
        report the electrical position so phase drive can be checked."""
        if n < 1:
            raise ValueError("n must be >= 1")
        self.wait()
        gap = interval_ms * 1000 - STEP_PULSE_US
        if not 0 < gap <= MAX_TICKS:
            raise ValueError("interval_ms out of range")
        self.rmt.write_pulses([STEP_PULSE_US, gap] * n, True)
        while not self.rmt.wait_done():
            pass
        self.pos += n
        # One electrical cycle is 4 full steps.  Drivers such as A4988,
        # DRV8825 and TMC2xxx reset to 45 degrees (both phases at 71%).
        cycle = 4 * MICROSTEPS
        e = self.pos % cycle
        angle = 45.0 + 360.0 * e / cycle
        r = angle * 3.14159265 / 180.0
        print("step %d, microstep %d/%d in cycle, %.1f deg: "
              "ideal A %+.0f%% B %+.0f%% (if driver reset at power-up)"
              % (self.pos, e, cycle, angle % 360, 100 * cos(r), 100 * sin(r)))


    def enable(self, on):
        """Energize (True) or release (False) the motor."""
        self.enable_pin.value(1 if on else 0)


turntable = None
oled = None


def index(n=1):
    """REPL: index n eighths of a turn."""
    turntable.index(n)


def run(seconds):
    """REPL: rotate continuously for seconds, then decelerate to a stop."""
    turntable.run(seconds)


def step(n=1, interval_ms=10):
    """REPL: send n microsteps, interval_ms apart, and report phase."""
    turntable.step(n, interval_ms)


def enable(on=True):
    """REPL: energize (True) or release (False) the motor."""
    turntable.enable(on)


def stats(reset=True):
    """REPL: report piece handoff lateness since the last call."""
    turntable.stats(reset)


def loop():
    """REPL: run the pushbutton controller only (Ctrl-C to exit)."""
    turntable.loop()


def web():
    """REPL: run the pushbutton controller and web server (Ctrl-C to exit)."""
    import web as webui
    app = webui.make_app(turntable)

    async def both():
        asyncio.create_task(turntable.poll_task())
        await app.start_server(port=webui.PORT)

    try:
        asyncio.run(both())
    except KeyboardInterrupt:
        turntable.abort()
        raise
    finally:
        asyncio.new_event_loop()


def idf_free():
    """Free bytes in the ESP-IDF heap (what WiFi and lwIP allocate from)."""
    try:
        return sum(h[1] for h in esp32.idf_heap_info(esp32.HEAP_DATA))
    except (AttributeError, OSError):
        return -1


def show_ap(ip):
    """Show the access point SSID and setup page address, replacing the
    signon message."""
    import wifi
    import display
    oled.show(wifi.AP_SSID, "", *display.wrap(ip + "/wifi"))


def show_station(ip):
    """Show the mDNS name on rows 0-1 and the station IP below it."""
    import display
    import wifi
    c = display.centered
    rows = display.wrap(wifi.HOSTNAME + ".local") + display.wrap(ip)
    oled.show(*[c(r) for r in rows])


def main():
    global turntable, oled
    import display
    oled = display.Display(OLED_SDA_PIN, OLED_SCL_PIN, OLED_ADDR)
    oled.center(1, "Honu")
    oled.center(3, "HuliHuli")
    # Pins first (UV off, motor enabled), so nothing floats while WiFi
    # takes up to ~20 s to connect or give up
    turntable = Turntable(oled)
    print("HonuHuliHuli: %d steps/rev, %d steps per 1/%d turn"
          % (STEPS_PER_REV, STEPS_PER_INDEX, DIVISIONS))
    print("REPL commands: index(n), run(seconds), step(n), enable(bool),"
          " stats(), loop(), web()")
    import wifi
    try:
        if turntable.button.stable:
            # Button held at power-up: provisioning mode
            print("Button held; starting access point")
            ip = None
        else:
            ip = wifi.connect()
        if ip:
            show_station(ip)
        else:
            show_ap(wifi.start_ap())
        # Tables after WiFi has its memory
        turntable.build()
        print("Free memory after precomputing: Python heap %d, ESP-IDF heap %d"
              % (gc.mem_free(), idf_free()))
        web()
    except KeyboardInterrupt:
        print("Interrupted; REPL commands available")


if __name__ == "__main__":
    main()
